/**
 * components/shared/pdf/K1.js - Schedule K-1 (Form 1065) per partner.
 *
 * Single-page document fed by buildK1() output: Part A (partnership), Part B
 * (partner), Part C (current-year distributive share + capital account analysis).
 *
 * Used by: TaxCenter (Financials > Tax Center).
 *
 * @perf lazy-load only (heavy @react-pdf/renderer); never import at top level.
 * @security partner SSN/TIN (partB.tax_id) is printed here; it reaches the PDF
 *           only via the audit-logged get_profile_tax_id path. @see docs/MONEY.md (tax)
 */
import React from 'react';
import { Document, Page, Text, View, StyleSheet } from '@react-pdf/renderer';
import { formatTaxAmount } from '../../../utils/ledger-tax';
import { PRINT } from '../../../utils/printPalette';

const P = PRINT;

const s = StyleSheet.create({
  page:     { padding: 36, fontFamily: 'Helvetica', fontSize: 9, color: P.nearBlack, backgroundColor: P.warmWhite },
  title:    { fontSize: 16, fontWeight: 700 },
  subtitle: { fontSize: 10, color: P.muted, marginBottom: 14 },
  section:  { marginTop: 14, fontSize: 11, color: P.orange, textTransform: 'uppercase', letterSpacing: 1, paddingBottom: 3, borderBottomWidth: 0.5, borderBottomColor: P.rule, borderBottomStyle: 'solid' },
  partyRow: { flexDirection: 'row', gap: 24 },
  partyCol: { flex: 1 },
  partyL:   { fontSize: 8, color: P.muted, textTransform: 'uppercase', letterSpacing: 1 },
  partyV:   { fontSize: 10, marginTop: 2 },
  row:      { flexDirection: 'row', paddingVertical: 3 },
  box:      { width: 50 },
  label:    { flex: 1 },
  amt:      { width: 110, textAlign: 'right' },
  capRow:   { flexDirection: 'row', paddingVertical: 3 },
  capLabel: { flex: 1 },
  capAmt:   { width: 130, textAlign: 'right' },
  total:    { flexDirection: 'row', paddingVertical: 5, borderTopWidth: 0.5, borderTopColor: P.nearBlack, borderTopStyle: 'solid', fontWeight: 700, marginTop: 4 },
  footer:   { position: 'absolute', bottom: 18, left: 36, right: 36, textAlign: 'center', fontSize: 8, color: P.muted, letterSpacing: 1 },
});

const F = (n) => formatTaxAmount(n);

function PartyBlock({ label, name, addr1, addr2, idLabel, id }) {
  return (
    <View style={s.partyCol}>
      <Text style={s.partyL}>{label}</Text>
      <Text style={s.partyV}>{name || '—'}</Text>
      <Text style={s.partyV}>{addr1 || ''}</Text>
      <Text style={s.partyV}>{addr2 || ''}</Text>
      {idLabel ? <Text style={[s.partyL, { marginTop: 4 }]}>{idLabel}</Text> : null}
      {idLabel ? <Text style={s.partyV}>{id || '—'}</Text> : null}
    </View>
  );
}

/**
 * The single-page K-1 document.
 * @param {object} props
 * @param {object} props.k1 - buildK1() output ({ fiscalYear, partA, partB, partC }); renders null when absent.
 */
export default function K1Document({ k1 }) {
  if (!k1) return null;
  const { fiscalYear, partA, partB, partC } = k1;
  const partnerAddr2 = [partB.city, partB.state_province, partB.postal_code].filter(Boolean).join(', ');
  const llcAddr2     = [partA.city, partA.state_province, partA.postal_code].filter(Boolean).join(', ');

  return (
    <Document>
      <Page size="LETTER" style={s.page}>
        <Text style={s.title}>Schedule K-1 (Form 1065)</Text>
        <Text style={s.subtitle}>Partner's Share of Income, Deductions, Credits, etc. · FY {fiscalYear}</Text>

        <Text style={s.section}>Part A: Information about the Partnership</Text>
        <PartyBlock
          label="Partnership"
          name={partA.legal_name}
          addr1={partA.street_address}
          addr2={llcAddr2}
          idLabel="Partnership EIN"
          id={partA.ein}
        />

        <Text style={s.section}>Part B: Information about the Partner</Text>
        <View style={s.partyRow}>
          <PartyBlock
            label="Partner name + address"
            name={partB.full_name}
            addr1={partB.street_address}
            addr2={partnerAddr2}
            idLabel="SSN / TIN"
            id={partB.tax_id}
          />
          <View style={s.partyCol}>
            <Text style={s.partyL}>Partner type</Text>
            <Text style={s.partyV}>{partB.partnerType}</Text>
            <Text style={[s.partyL, { marginTop: 4 }]}>Domestic / Foreign</Text>
            <Text style={s.partyV}>{partB.domesticOrForeign}</Text>
            <Text style={[s.partyL, { marginTop: 4 }]}>Profit / Loss / Capital share</Text>
            <Text style={s.partyV}>{partC.allocationPct}%</Text>
          </View>
        </View>

        <Text style={s.section}>Part C: Partner's Share of Current Year Income, Deductions, Credits</Text>
        <View style={s.row}>
          <Text style={s.box}>Box 1</Text>
          <Text style={s.label}>Ordinary business income (loss)</Text>
          <Text style={[s.amt, { color: P.orange, fontWeight: 700 }]}>{F(partC.box1)}</Text>
        </View>
        <View style={s.row}>
          <Text style={s.box}>Box 4a</Text>
          <Text style={s.label}>Guaranteed payments for services</Text>
          <Text style={s.amt}>{F(partC.box4a)}</Text>
        </View>
        <View style={s.row}>
          <Text style={s.box}>Box 13</Text>
          <Text style={s.label}>Other deductions</Text>
          <Text style={s.amt}>{F(partC.box13)}</Text>
        </View>
        <View style={s.row}>
          <Text style={s.box}>Box 14A</Text>
          <Text style={s.label}>Self-employment earnings (loss)</Text>
          <Text style={s.amt}>{F(partC.box14A)}</Text>
        </View>
        <View style={s.row}>
          <Text style={s.box}>Box 19A</Text>
          <Text style={s.label}>Distributions of cash and marketable securities</Text>
          <Text style={s.amt}>{F(partC.box19A)}</Text>
        </View>

        {partC.capital ? (
          <>
            <Text style={s.section}>Item L: Partner's Capital Account Analysis</Text>
            <View style={s.capRow}><Text style={s.capLabel}>Beginning capital account</Text><Text style={s.capAmt}>{F(partC.capital.beginning)}</Text></View>
            <View style={s.capRow}><Text style={s.capLabel}>Current year increase (income share + contributions)</Text><Text style={s.capAmt}>{F(partC.capital.currentYearIncrease)}</Text></View>
            <View style={s.capRow}><Text style={s.capLabel}>Current year decrease (distributions)</Text><Text style={s.capAmt}>{F(partC.capital.currentYearDecrease)}</Text></View>
            <View style={s.total}><Text style={s.capLabel}>Ending capital account</Text><Text style={s.capAmt}>{F(partC.capital.ending)}</Text></View>
          </>
        ) : null}

        <Text style={s.footer}>Schedule K-1 · FY {fiscalYear} · Generated from Nysterys ledger</Text>
      </Page>
    </Document>
  );
}
